\u0645\u0633\u0637\u062d \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0628\u0636 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u0643.\n\u0627\u0646\u062d\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0645\u0646 \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0628\u0636 \u0646\u062d\u0648 \u062c\u0630\u0639\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0633\u062d\u0628 \u0644\u0648\u062d \u0643\u062a\u0641\u0643 \u0648\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0642\u0631\u064a\u0628\u0629 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0642\u0645 \u0628\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0623\u062f\u0627\u0621 \u0627\u0644\u062a\u0645\u0631\u064a\u0646 \u0628\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2464","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2464-ZgwWBoC.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2464-ZgwWBoC.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bd02d84e-c8a1-548e-8352-f431451b5746","source_id":"0241","name_en":"cable triceps pushdown (v-bar)","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0636\u063a\u0637 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0644\u0644\u0623\u0633\u0641\u0644 (v-bar)","match_names":["cable triceps pushdown (v-bar)"],"muscle":"triceps","equipment":"cable","aliases":["cable triceps pushdown (v-bar)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a v-bar attachment to the cable machine at the highest setting.\nStand facing the cable machine with your feet shoulder-width apart.\nGrasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.\nKeep your elbows close to your sides and your upper arms stationary throughout the exercise.\nEngage your triceps and exhale as you push the v-bar down until your arms are fully extended.\nPause for a moment at the bottom of the movement, squeezing your triceps.\nInhale as you slowly return the v-bar to the starting position, maintaining control.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0644\u062d\u0642 v-bar \u0628\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0623\u0639\u0644\u0649 \u0625\u0639\u062f\u0627\u062f.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0639\u0644\u0649 \u0634\u0643\u0644 \u062d\u0631\u0641 V \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0648\u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0645\u062a\u062c\u0647\u062a\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644\u060c \u0648\u064a\u062f\u064a\u0643 \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u0627\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0628\u064a\u0646\u0645\u0627 \u062a\u0636\u063a\u0637 \u0639\u0644\u0649 \u0634\u0631\u064a\u0637 v \u0644\u0623\u0633\u0641\u0644 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0623\u062b\u0646\u0627\u0621 \u0625\u0631\u062c\u0627\u0639 \u0634\u0631\u064a\u0637 v \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0241","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0241-gAwDzB3.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0241-gAwDzB3.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"94a9e062-0aee-5939-8724-68b29e9107e5","source_id":"2405","name_en":"cable triceps pushdown (v-bar) (with arm blaster)","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0636\u063a\u0637 \u0627\u0644\u0639\u0636\u0644\u0629 \