627\u0639\u062f\u062a\u0627\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0648\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0628\u064a\u0646\u0645\u0627 \u062a\u0636\u063a\u0637 \u0639\u0644\u0649 \u0634\u0631\u064a\u0637 v \u0644\u0623\u0633\u0641\u0644 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0623\u062b\u0646\u0627\u0621 \u0625\u0631\u062c\u0627\u0639 \u0634\u0631\u064a\u0637 v \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0643\u0645.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2405","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2405-OxJk1fg.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2405-OxJk1fg.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e10ad7a3-74cc-5b17-8e0d-5726598e3904","source_id":"0242","name_en":"cable tuck reverse crunch","name_ar":"\u0623\u0632\u0645\u0629 \u0639\u0643\u0633\u064a\u0629 \u0644\u062b\u0646\u064a\u0629 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable tuck reverse crunch"],"muscle":"core","equipment":"cable","aliases":["cable tuck reverse crunch"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a cable to a low pulley and lie down on a mat facing up.\nHold the cable with both hands and extend your arms straight up above your chest.\nBend your knees and lift your legs up, bringing your knees towards your chest.\nAt the same time, curl your pelvis up towards your chest, lifting your hips off the ground.\nPause for a moment at the top, then slowly lower your legs and hips back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0643\u0627\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0633\u062a\u0644\u0642 \u0639\u0644\u0649 \u062d\u0635\u064a\u0631\u0629 \u0645\u062a\u062c\u0647\u064b\u0627 \u0644\u0623\u0639\u0644\u0649.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0641\u0648\u0642 \u0635\u062f\u0631\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0628\u062d\u064a\u062b \u062a\u0635\u0644 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647\u060c \u0627\u0631\u0641\u0639\u064a \u062d\u0648\u0636\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0631\u0641\u0639\u064a \u0648\u0631\u0643\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0648\u0648\u0631\u0643\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0242","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0242-TXtXc84.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0242-TXtXc84.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c375bcd8-9daa-5ff0-8160-73c40cc78705","source_id":"0243","name_en":"cable twist","name_ar":"\u062a\u0637\u0648\u0631 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable twist"],"muscle":"core","equipment":"cable","aliases":["cable twist"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart, facing the cable machine.\nHold the cable handle with both hands in front of your chest, keeping your arms slightly bent.\nEngage your core and twist your torso to the right, pulling the cable across your body.\nPause for a moment at the end of the movement, feeling the contraction in your abs and obliques.\nSlowly return to the starting position, resisting the cable''s pull.\nRepeat the movement to the left side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u062b\u0646\u064a\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0628\u0631 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634 \u0641\u064a \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0628\u0637\u0646 \u0648\u0627\u0644\u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0627\u0626\u0644\u0629.\n\u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0648\u0642\u0627\u0648\u0645 \u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0243","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0243-aVs3BR3.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0243-aVs3BR3.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"67ce6a43-94ce-5201-8412-362584c44306","source_id":"0862","name_en":"cable twist (up-down)","name_ar":"\u062a\u0637\u0648\u0631 \u0627\u0644\u0643\u0627\u0628\u0644 (\u0645\u0646 \u0623\u0639\u0644\u0649 \u0625\u0644\u0649 \u0623\u0633\u0641\u0644)","match_names":["cable twist (up-down)"],"muscle":"core","equipment":"cable","aliases":["cable twist (up-down)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart, facing the cable machine.\nHold the cable handle with both hands in front of your chest, keeping your arms slightly bent.\nEngage your core and slowly rotate your torso to one side, keeping your hips and legs stable.\nPause for a moment at the end of the rotation, then slowly return to the starting position.\nRepeat the rotation to the opposite side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0643\u0644\u062a\u0627 \u064a\u062f\u064a\u0643 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u062b\u0646\u064a\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0633\u0627\u0642\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062f\u0648\u0631\u0627\u0646\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0862","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0862-fhZQPlV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0862-fhZQPlV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d68863a4-5343-512a-82e5-ef63076ebe14","source_id":"0244","name_en":"cable twisting pull","name_ar":"\u0633\u062d\u0628 \u0627\u0644\u062a\u0648\u0627\u0621 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable twisting pull"],"muscle":"back","equipment":"cable","aliases":["cable twisting pull"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a cable handle to a low pulley and stand facing the machine.\nGrasp the handle with your left hand and step away from the machine, extending your arm fully.\nPosition your feet shoulder-width apart, with your knees slightly bent.\nKeep your back straight and your core engaged throughout the exercise.\nPull the handle towards your body, rotating your torso to the right as you do so.\nSqueeze your back muscles at the end of the movement.\nSlowly return to the starting position, keeping tension on the cable.\nRepeat for the desired number of repetitions, then switch sides and perform with your right hand.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0627\u0644\u0648\u0642\u0648\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0628\u0636 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0628\u062a\u0639\u062f \u0639\u0646 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0628\u0636 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643\u060c \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646 \u0623\u062b\u0646\u0627\u0621 \u0642\u064a\u0627\u0645\u0643 \u0628\u0630\u0644\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0634\u062f \u0627\u0644\u0643\u0627\u0628\u0644.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0648\u0642\u0645 \u0628\u0627\u0644\u062a\u0646\u0641\u064a\u0630 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0244","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["shoulders","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0244-zCgxPbV.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0244-zCgxPbV.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3fb0e80b-cd9a-5086-8fbd-bdd926a3105e","source_id":"1645","name_en":"cable two arm curl on incline bench","name_ar":"\u0642\u0645 \u0628\u062a\u062c\u0639\u064a\u062f \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0630\u0631\u0627\u0639\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0627\u0644\u0645\u0627\u0626\u0644","match_names":["cable two arm curl on incline bench"],"muscle":"biceps","equipment":"cable","aliases":["cable two arm curl on incline bench"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on an incline bench with your back against the pad and your feet flat on the ground.\nGrasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.\nKeeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.\nPause for a moment at the top of the movement, squeezing your biceps.\nInhale and slowly lower the handles back to the starting position, fully extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643 \u0623\u062b\u0646\u0627\u0621 \u0642\u0628\u0636 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646.\n\u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1645","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1645-H9y3Dkr.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1645-H9y3Dkr.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"30b1363c-27aa-52e3-8531-6eb241c68cd7","source_id":"1728","name_en":"cable two arm tricep kickback","name_ar":"\u0643\u0627\u0628\u0644 \u0630\u0648 \u0630\u0631\u0627\u0639\u064a\u0646 \u0631\u0634\u0648\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633","match_names":["cable two arm tricep kickback"],"muscle":"triceps","equipment":"cable","aliases":["cable two arm tricep kickback"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and knees slightly bent.\nHold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.\nKeeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.\nPause for a moment, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u062f\u0627\u062e\u0644 \u0648\u062b\u0646\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u062a\u064a\u0646 \u062b\u0627\u0628\u062a\u062a\u064a\u0646\u060c \u0648\u0645\u062f \u0633\u0627\u0639\u062f\u064a\u0643 \u0644\u0644\u062e\u0644\u0641 \u062d\u062a\u0649 \u064a\u062a\u0645 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1728","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1728-vvNjDJS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1728-vvNjDJS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"629d0023-292d-5988-84a7-2c3db69e34d4","source_id":"0245","name_en":"cable underhand pulldown","name_ar":"\u0643\u0627\u0628\u0644 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629","match_names":["cable underhand pulldown"],"muscle":"back","equipment":"cable","aliases":["cable underhand pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the cable machine so that the pulldown bar is at a height above your head.\nSit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.\nKeep your back straight and lean back slightly.\nPull the bar down towards your chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0646\u0633\u062f\u0644 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u0636\u064a\u0628 \u0627\u0644\u0645\u0646\u0633\u062f\u0644 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0631\u062c\u0639 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0628\u0627\u0631 \u0644\u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0245","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0245-xBYcQHj.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0245-xBYcQHj.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a92e19f7-f2da-567b-8556-c07c4950143a","source_id":"1270","name_en":"cable upper chest crossovers","name_ar":"\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u0635\u062f\u0631","match_names":["cable upper chest crossovers"],"muscle":"chest","equipment":"cable","aliases":["cable upper chest crossovers"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach the handles to the cables at chest height.\nStand in the center of the cable machine with one foot slightly in front of the other.\nGrasp the handles with your palms facing down and your arms extended out to the sides.\nKeep a slight bend in your elbows and engage your core.\nPull the cables together in front of your chest, crossing them over each other.\nSqueeze your chest muscles at the peak of the movement.\nSlowly release the cables back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0642\u0641 \u0641\u064a \u0645\u0646\u062a\u0635\u0641 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0625\u062d\u062f\u0649 \u0627\u0644\u0642\u062f\u0645\u064a\u0646 \u0623\u0645\u0627\u0645 \u0627\u0644\u0623\u062e\u0631\u0649 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u062a\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0646\u062d\u0646\u0627\u0621 \u0637\u0641\u064a\u0641 \u0641\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0645\u0639\u064b\u0627 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0639\u0628\u0648\u0631\u0647\u0627 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0641\u064a \u0630\u0631\u0648\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0631 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1270","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["deltoids","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1270-j7XMAyn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1270-j7XMAyn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"857070b1-3600-5ba9-81d6-00db5847b68c","source_id":"1324","name_en":"cable upper row","name_ar":"\u0643\u0627\u0628\u0644 \u0627\u0644\u0635\u0641 \u0627\u0644\u0639\u0644\u0648\u064a","match_names":["cable upper row"],"muscle":"back","equipment":"cable","aliases":["cable upper row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a straight bar to a cable machine at chest height.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\nKeep your back straight and your core engaged.\nPull the bar towards your upper chest, squeezing your shoulder blades together.\nPause for a moment at the top of the movement.\nSlowly release the bar back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062a\u0641\u0627\u0639\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0646\u062d\u0648 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0623\u0639\u0644\u0649 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1324","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1324-PQStVXH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1324-PQStVXH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b7b73a30-f953-5f52-8047-54d726606853","source_id":"0246","name_en":"cable upright row","name_ar":"\u0635\u0641 \u0627\u0644\u0643\u0627\u0628\u0644 \u0641\u064a \u0648\u0636\u0639 \u0645\u0633\u062a\u0642\u064a\u0645","match_names":["cable upright row"],"muscle":"shoulders","equipment":"cable","aliases":["cable upright row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.\nKeep your back straight and your core engaged throughout the exercise.\nPull the cable attachment straight up towards your chin, leading with your elbows.\nPause for a moment at the top, squeezing your shoulder blades together.\nSlowly lower the cable attachment back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0645\u0631\u0641\u0642 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0646\u0634\u0627\u0637\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0633\u062d\u0628 \u0645\u0644\u062d\u0642 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0630\u0642\u0646\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0645\u0631\u0641\u0642 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0246","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["traps","biceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0246-cALKspW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0246-cALKspW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1d369317-6937-53d6-8779-9b62d677fc75","source_id":"1325","name_en":"cable wide grip rear pulldown behind neck","name_ar":"\u0643\u0627\u0628\u0644 \u0645\u0646\u0633\u062f\u0644 \u062e\u0644\u0641\u064a \u0628\u0642\u0628\u0636\u0629 \u0648\u0627\u0633\u0639\u0629 \u062e\u0644\u0641 \u0627\u0644\u0631\u0642\u0628\u0629","match_names":["cable wide grip rear pulldown behind neck"],"muscle":"back","equipment":"cable","aliases":["cable wide grip rear pulldown behind neck"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the cable machine so that the pulldown bar is at a height above your head.\nSit down on the seat and grab the pulldown bar with a wide overhand grip.\nKeep your back straight and your chest up as you lean back slightly.\nPull the bar down towards your upper chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0646\u0633\u062f\u0644 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0634\u0631\u064a\u0637 \u0627\u0644\u0645\u0646\u0633\u062f\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0648\u0627\u0633\u0639\u0629.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u064a\u0646\u0645\u0627 \u062a\u0645\u064a\u0644 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0628\u0627\u0631 \u0644\u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1325","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1325-CmEr4pM.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1325-CmEr4pM.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c6be41ea-2499-5658-8b2f-14e68ccadb5e","source_id":"0247","name_en":"cable wrist curl","name_ar":"\u062a\u062c\u0639\u064a\u062f \u0645\u0639\u0635\u0645 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable wrist curl"],"muscle":"forearms","equipment":"cable","aliases":["cable wrist curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a straight bar to a low pulley cable machine.\nStand facing the machine with your feet shoulder-width apart.\nGrasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.\nRest your forearms on a bench or pad, with your wrists hanging off the edge.\nKeeping your forearms stationary, exhale and curl your wrists upward as far as possible.\nPause for a moment at the top, then inhale and slowly lower the bar back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0625\u0628\u0639\u0627\u062f \u064a\u062f\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0648\u0633\u0627\u062f\u0629\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0645\u0639\u0635\u0645\u064a\u0643 \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0623\u0628\u0642\u0650 \u0633\u0627\u0639\u062f\u064a\u0643 \u062b\u0627\u0628\u062a\u064a\u0646\u060c \u062b\u0645 \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0644\u0641 \u0645\u0639\u0635\u0645\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u0648\u0627\u062e\u0641\u0636 \u0627\u0644\u0628\u0627\u0631 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0247","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["biceps","brachialis"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0247-LrV4s90.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0247-LrV4s90.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"ff414830-1b2f-53bd-83d8-040ed0f27e30","source_id":"1407","name_en":"calf push stretch with hands against wall","name_ar":"\u062a\u0645\u062f\u064a\u062f \u062f\u0641\u0639 \u0631\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0642 \u0628\u0627\u0644\u0623\u064a\u062f\u064a \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637","match_names":["calf push stretch with hands against wall"],"muscle":"calves","equipment":"bodyweight","aliases":["calf push stretch with hands against wall"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing a wall with your feet hip-width apart.\nPlace your hands against the wall at shoulder height.\nStep back with one foot, keeping your heel on the ground and your leg straight.\nBend your front knee slightly and lean forward, feeling a stretch in your calf.\nHold the stretch for 20-30 seconds.\nSwitch legs and repeat the stretch.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062d\u0627\u0626\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0639\u062f \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0633\u0627\u0642\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u0623\u0645\u0627\u0645\u064a\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0631\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0642.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1407","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1407-PzNxakt.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1407-PzNxakt.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"18b82a04-0842-567c-8b6d-72bdd709b837","source_id":"1377","name_en":"calf stretch with hands against wall","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0639\u062c\u0644 \u0645\u0639 \u0627\u0644\u064a\u062f\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637","match_names":["calf stretch with hands against wall"],"muscle":"calves","equipment":"bodyweight","aliases":["calf stretch with hands against wall"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand facing a wall with your feet hip-width apart.\nPlace your hands against the wall at shoulder height.\nStep your right foot back, keeping your heel on the ground and your leg straight.\nBend your left knee and lean forward, keeping your back leg straight and your heel on the ground.\nHold the stretch for 20-30 seconds.\nSwitch legs and repeat the stretch.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u062d\u0627\u0626\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0631\u062c\u0639\u064a \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0633\u0627\u0642\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0633\u0627\u0642\u0643 \u0627\u0644\u062e\u0644\u0641\u064a\u0629 \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u0648\u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1377","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1377-m0tCHqc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1377-m0tCHqc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f8b72df5-2134-500d-8689-5d22ff12678e","source_id":"1378","name_en":"calf stretch with rope","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0639\u062c\u0644 \u0628\u0627\u0644\u062d\u0628\u0644","match_names":["calf stretch with rope"],"muscle":"calves","equipment":"rope","aliases":["calf stretch with rope"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Stand facing a wall or sturdy object with your feet hip-width apart.\nHold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.\nStep back with your left foot, keeping your heel on the ground and your leg straight.\nLean forward, keeping your back straight, and gently pull on the rope to stretch your calf.\nHold the stretch for 20-30 seconds, then release.\nRepeat on the other leg.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u062f\u0627\u0631 \u0623\u0648 \u062c\u0633\u0645 \u0642\u0648\u064a \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0623\u0645\u0633\u0643 \u0637\u0631\u0641\u064a \u0627\u0644\u062d\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u062b\u0645 \u0636\u0639 \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u062d\u0628\u0644 \u062d\u0648\u0644 \u0643\u0631\u0629 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0628\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0633\u0627\u0642\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0629.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643\u060c \u0648\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u0628\u0644 \u0628\u0631\u0641\u0642 \u0644\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1378","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1378-1LVFcEn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1378-1LVFcEn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2eb6dedb-f225-5e86-8d0d-e5119d05ee10","source_id":"0248","name_en":"cambered bar lying row","name_ar":"\u0634\u0631\u064a\u0637 \u0645\u062d\u062f\u0628 \u0635\u0641 \u0627\u0644\u0643\u0630\u0628","match_names":["cambered bar lying row"],"muscle":"back","equipment":"barbell","aliases":["cambered bar lying row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.\nReach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.\nWith your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.\nPull the barbell towards your chest, squeezing your shoulder blades together.\nLower the barbell back down to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0642\u0645 \u0628\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644 \u0648\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0623\u0639\u0631\u0636 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u0639 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0633\u0627\u0642\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062d\u062f\u064a\u062f \u0639\u0646 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062d\u062f\u064a\u062f \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062d\u062f\u064a\u062f \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u062b\u0645 \u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0248","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0248-R5swFnc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0248-R5swFnc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"672e254f-463c-50fd-8aef-3728a8fd86e4","source_id":"2963","name_en":"captains chair straight leg raise","name_ar":"\u0643\u0631\u0633\u064a \u0627\u0644\u0643\u0627\u0628\u062a\u0646 \u064a\u0631\u0641\u0639 \u0627\u0644\u0633\u0627\u0642 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645","match_names":["captains chair straight leg raise"],"muscle":"core","equipment":"bodyweight","aliases":["captains chair straight leg raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.\nKeep your upper body stable and your back straight.\nEngage your abs and lift your legs up in front of you, keeping them straight.\nContinue lifting until your legs are parallel to the ground or as high as you can comfortably go.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0643\u0631\u0633\u064a \u0627\u0644\u0642\u0628\u0637\u0627\u0646 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0633\u0627\u0639\u062f\u064a\u0643 \u0639\u0644\u0649 \u0648\u0633\u0627\u062f\u0627\u062a \u0627\u0644\u0630\u0631\u0627\u0639.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0631\u0627\u0631 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0631\u0641\u0639 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0633\u0627\u0642\u064a\u0643 \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636 \u0623\u0648 \u0625\u0644\u0649 \u0623\u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2963","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2963-weoDEpH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2963-weoDEpH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"62867c06-8db5-53e8-8ded-a218b2a71ae7","source_id":"1548","name_en":"chair leg extended stretch","name_ar":"\u062a\u0645\u062a\u062f \u0633\u0627\u0642 \u0627\u0644\u0643\u0631\u0633\u064a","match_names":["chair leg extended stretch"],"muscle":"quads","equipment":"bodyweight","aliases":["chair leg extended stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Sit on the edge of a chair with your back straight and feet flat on the ground.\nExtend one leg straight out in front of you, keeping your heel on the ground.\nLean forward slightly, feeling a stretch in your quadriceps.\nHold this position for 20-30 seconds.\nSwitch legs and repeat the stretch.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u0643\u0631\u0633\u064a \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0645\u062f \u0633\u0627\u0642 \u0648\u0627\u062d\u062f\u0629 \u0623\u0645\u0627\u0645\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0641\u062e\u0630 \u0627\u0644\u0631\u0628\u0627\u0639\u064a\u0629.\n\u0634\u063a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u0635\u0628 \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0642\u0645 \u0628\u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0648\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1548","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1548-xGgAGPm.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1548-xGgAGPm.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"706013a3-0131-5ee7-80e2-bfe65752dda3","source_id":"1271","name_en":"chest and front of shoulder stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0635\u062f\u0631 \u0648\u0623\u0645\u0627\u0645 \u0627\u0644\u0643\u062a\u0641","match_names":["chest and front of shoulder stretch"],"muscle":"chest","equipment":"bodyweight","aliases":["chest and front of shoulder stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand tall with your feet shoulder-width apart.\nExtend your arms straight out in front of you at shoulder height.\nCross your arms in front of your body, with your right arm on top of your left arm.\nInterlace your fingers and press your palms together.\nGently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.\nHold the stretch for 20-30 seconds, then release.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0637\u0648\u064a\u0644\u064b\u0627 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u0623\u0645\u0627\u0645\u0643 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0648\u0636\u0639 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0641\u0648\u0642 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0642\u0645 \u0628\u0634\u0628\u0643 \u0623\u0635\u0627\u0628\u0639\u0643 \u0648\u0627\u0636\u063a\u0637 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u0627\u0636\u063a\u0637 \u0628\u0644\u0637\u0641 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0648\u0627\u062f\u0641\u0639 \u064a\u062f\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643 \u0648\u0623\u0645\u0627\u0645 \u0643\u062a\u0641\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u062a\u0631\u0643\u0647.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1271","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1271-Uto7l43.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1271-Uto7l43.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"cda604dd-3633-5639-8bd1-4ec27820fe3b","source_id":"0251","name_en":"chest dip","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0635\u062f\u0631","match_names":["chest dip"],"muscle":"chest","equipment":"bodyweight","aliases":["chest dip"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Position yourself on parallel bars with your arms fully extended and your body straight.\nLower your body by bending your elbows until your shoulders are below your elbows.\nPush yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u0646\u0641\u0633\u0643 \u0639\u0644\u0649 \u0642\u0636\u0628\u0627\u0646 \u0645\u062a\u0648\u0627\u0632\u064a\u0629 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u062d\u062a\u0649 \u064a\u0635\u0628\u062d \u0643\u062a\u0641\u064a\u0643 \u062a\u062d\u062a \u0645\u0631\u0641\u0642\u064a\u0643.\n\u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0251","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0251-9WTm7dq.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0251-9WTm7dq.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f6be32ec-b392-5a93-80c6-685518b87557","source_id":"1430","name_en":"chest dip (on dip-pull-up cage)","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0635\u062f\u0631 (\u0639\u0644\u0649 \u0642\u0641\u0635 \u0627\u0644\u0633\u062d\u0628 \u0644\u0623\u0639\u0644\u0649)","match_names":["chest dip (on dip-pull-up cage)"],"muscle":"chest","equipment":"bodyweight","aliases":["chest dip (on dip-pull-up cage)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Adjust the dip bars to a height that allows you to comfortably grip them.\nStand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.\nJump up and straighten your arms, supporting your body weight on the bars.\nBend your knees and cross your ankles behind you.\nLower your body by bending your elbows, keeping your chest up and your shoulders down.\nContinue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.\nPush through your palms and extend your elbows to raise your body back up to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0642\u0636\u0628\u0627\u0646 \u0627\u0644\u0627\u0646\u062d\u062f\u0627\u0631 \u0639\u0644\u0649 \u0627\u0644\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0630\u064a \u064a\u0633\u0645\u062d \u0644\u0643 \u0628\u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0647\u0627 \u0628\u0634\u0643\u0644 \u0645\u0631\u064a\u062d.\n\u0642\u0641 \u0628\u064a\u0646 \u0627\u0644\u0642\u0636\u0628\u0627\u0646 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0643\u0644 \u0634\u0631\u064a\u0637\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u0628\u0627\u0639\u062f\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0642\u0641\u0632 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0642\u0645 \u0628\u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643\u060c \u0645\u0639 \u062f\u0639\u0645 \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u0642\u0636\u0628\u0627\u0646.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0627\u0639\u0628\u0631 \u0643\u0627\u062d\u0644\u064a\u0643 \u062e\u0644\u0641\u0643.\n\u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0627\u0646\u062e\u0641\u0627\u0636 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0643\u062a\u0641\u064a\u0643 \u062a\u062d\u062a \u0645\u0631\u0641\u0642\u064a\u0643 \u0623\u0648 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0635\u062f\u0631\u0643.\n\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0631\u0641\u0639 \u062c\u0633\u0645\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1430","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1430-XgWyAiA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1430-XgWyAiA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"816ee1b8-65d3-5ddc-870a-6c1292f307b4","source_id":"2462","name_en":"chest dip on straight bar","name_ar":"\u062a\u0631\u0627\u062c\u0639 \u0627\u0644\u0635\u062f\u0631 \u0639\u0644\u0649 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645","match_names":["chest dip on straight bar"],"muscle":"chest","equipment":"bodyweight","aliases":["chest dip on straight bar"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Grab the parallel bars with your palms facing down and your arms fully extended.\nBend your knees and cross your ankles.\nLower your body by bending your arms until your shoulders are below your elbows.\nPush yourself back up to the starting position by straightening your arms.\nRepeat for the desired number of repetitions.","