eight","aliases":["close-grip push-up (on knees)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.\nLower your upper body towards the ground by bending your elbows, keeping them close to your sides.\nPause for a moment when your chest is just above the ground.\nPush through your palms to straighten your arms and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0639\u0644\u0649 \u064a\u062f\u064a\u0643 \u0648\u0631\u0643\u0628\u062a\u064a\u0643\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0639\u0631\u0636 \u0627\u0644\u0648\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f\u0645\u0627 \u064a\u0643\u0648\u0646 \u0635\u062f\u0631\u0643 \u0641\u0648\u0642 \u0627\u0644\u0623\u0631\u0636 \u0645\u0628\u0627\u0634\u0631\u0629\u064b.\n\u0627\u062f\u0641\u0639 \u0628\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u062a\u0635\u0648\u064a\u0628 \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2398","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["chest","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2398-v3vLFW0.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2398-v3vLFW0.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f86fc61b-fd01-5f43-83f1-22987ef9ac45","source_id":"0260","name_en":"cocoons","name_ar":"\u0634\u0631\u0627\u0646\u0642","match_names":["cocoons"],"muscle":"core","equipment":"bodyweight","aliases":["cocoons"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\